// 4. Sınıf Günlük Hikâyeler — özgün, orta uzunlukta hikâyeler ve anlama soruları
window.HIKAYELER = [
  { id: "d01", baslik: "Kayıp Cüzdan", resim: "👛 🚌 😊", ders: "Dürüstlük, kimse görmese bile doğru olanı yapmaktır.",
    metin: ["Okul servisinden inen Ömer, koltuğun altında kahverengi bir cüzdan gördü. İçinde para ve bir kimlik kartı vardı. Arkadaşı Burak, \"Kimse görmedi, paraları alalım.\" dedi.", "Ömer cüzdanı eline aldığında kalbi hızla çarpıyordu. Cüzdanın içinde birkaç banknot, bir otobüs kartı ve küçük, eski bir fotoğraf vardı. Fotoğrafta yaşlı bir kadın, kucağındaki bebeğe gülümsüyordu. Ömer fotoğrafa uzun uzun baktı. \"Bu cüzdan birinin hatırası, birinin ihtiyacı.\" diye düşündü. Burak ise sabırsızca ayağını yere vuruyordu: \"Hadi, kimse bilmeyecek!\"", "Ömer bir an durdu. Annesinin, \"Bir şeyin sahibi olmadığında, o şeyin sorumluluğu sana geçer.\" sözünü hatırladı. Cüzdanı alıp servis şoförü Recep Amca'ya verdi.", "Ömer, Burak'a döndü: \"Kimse bilmese bile ben bilirim. Ayrıca bu paranın sahibi şu an çok üzülüyordur. Senin cüzdanın kaybolsaydı ne hissederdin?\" Burak bir an sustu. Geçen yıl yeni aldığı montunu parkta unuttuğunu ve bir daha bulamadığını hatırladı. O gün ne kadar ağladığını düşününce başını önüne eğdi.", "Recep Amca kimlikteki ismi okuyunca gülümsedi. Cüzdan, her sabah servisi bekleyen yaşlı Ayten Teyze'nindi. İçinde ilaç parası olduğunu söyleyerek ağlamıştı.", "Ayten Teyze o sabah cüzdanını kaybettiğini fark edince bütün yolu geri yürümüş, çöp kutularına bile bakmıştı. Cüzdanında ayın sonuna kadar yetmesi gereken ilaç parası vardı. Recep Amca onu arayıp cüzdanın bulunduğunu söylediğinde telefonda sevinçten ağlamaya başladı. \"Bulan çocuğun adını öğrenmek istiyorum.\" dedi.", "Ertesi gün Ayten Teyze, Ömer'in sınıfına geldi. Elinde bir tepsi kurabiye vardı. \"Senin gibi dürüst çocuklar oldukça bu dünya güzel kalacak.\" dedi. Burak o gün Ömer'e bir söz verdi: Bir daha asla başkasının malına göz dikmeyecekti.", "O akşam Ömer olanları annesine anlattı. Annesi onu sıkıca kucakladı: \"Bugün yaptığın şey, kazanabileceğin bütün paralardan daha değerli. Çünkü insanlar artık sana güvenecek.\" Ömer yatağına uzandığında içinde tarif edemediği bir huzur vardı. Doğru olanı yapmanın insanın içini ısıttığını ilk kez bu kadar güçlü hissetmişti."],
    sorular: [["Ömer cüzdanı nerede buldu?", "Servis koltuğunun altında", ["Okul bahçesinde", "Kantinde"]], ["Burak ne önerdi?", "Paraları almayı", ["Polise götürmeyi", "Öğretmene vermeyi"]], ["Cüzdan kimindi?", "Ayten Teyze'nin", ["Recep Amca'nın", "Burak'ın annesinin"]], ["Cüzdandaki para ne içindi?", "İlaç almak için", ["Tatil için", "Hediye için"]]] },
  { id: "d02", baslik: "Çınarın Gölgesinde", resim: "🌳 👴 📖", ders: "Bugün dikilen bir fidan, gelecek nesillere armağandır.",
    metin: ["Köy meydanındaki dev çınarın altında her akşam yaşlılar oturur, çocuklar oynardı. Bir gün Zehra, dedesine bu ağacı kimin diktiğini sordu.", "Çınarın gövdesi o kadar kalındı ki beş çocuk el ele tutuşup sarılabiliyordu. Yazın en sıcak günlerinde bile gölgesi serin olurdu. Köyün düğünleri, bayram şenlikleri ve hasat kutlamaları hep onun altında yapılırdı. Dallarında serçeler, kumrular ve bir çift baykuş yaşıyordu. Zehra'ya göre bu ağaç köyün en yaşlı ve en bilge sakiniydi.", "Dedesi gülümsedi: \"Bu çınarı benim dedem dikmiş, yüz yıldan da önce. Kendisi gölgesinde hiç oturamamış ama bizim için dikmiş.\" Zehra çok şaşırdı. İnsan neden göremeyeceği bir ağacı dikerdi ki?", "Dedesi Zehra'yı çınarın arkasına götürdü ve gövdedeki eski bir çentiği gösterdi. \"Dedem bu ağacı diktiğinde benim yaşımdaymış. Her yıl boyunu bu çınarla ölçermiş. Sonra ağaç onu geçmiş, ondan sonra beni, babanı...\" Zehra elini çentiğe koydu. Yüz yıl önce aynı yerde duran bir çocuğu düşündü ve tüyleri diken diken oldu.", "Dedesi açıkladı: \"Biz de başkalarının diktiği ağaçların meyvesini yiyoruz. Biz de gelecektekiler için ağaç dikmeliyiz.\"", "Zehra o gece uyumadan önce düşündü. Okuldaki öğretmeni, bir ağacın bir yılda insanların soluduğu oksijenin önemli bir kısmını ürettiğini, toprağı tuttuğunu ve kuşlara yuva olduğunu anlatmıştı. Demek ki ağaç dikmek sadece gölge için değildi. Bir ağaç, yüz yıl boyunca hiç durmadan herkese iyilik yapan bir dost gibiydi.", "O bahar Zehra, okulda başlayan fidan dikme kampanyasına katıldı. Bahçenin köşesine küçük bir çınar fidanı dikti ve yanına bir tabela koydu: \"Gölgesinde oturacak çocuklara armağandır.\"", "Zehra her hafta fidanını suladı, çevresindeki otları temizledi. Bir fırtınadan sonra fidanın eğildiğini görünce dedesiyle birlikte yanına bir destek çubuğu çaktılar. Yaz sonunda fidanın üç yeni yaprak çıkardığını gördü ve sevinçle dedesine koştu. Dedesi gülümsedi: \"Bak, sen de artık gelecek için bir şey dikmiş oldun.\""],
    sorular: [["Çınarı kim dikmiş?", "Dedesinin dedesi", ["Zehra'nın babası", "Köyün öğretmeni"]], ["Çınar kaç yıllık?", "Yüz yıldan fazla", ["On yıllık", "Beş yıllık"]], ["Zehra hangi kampanyaya katıldı?", "Fidan dikme", ["Kitap toplama", "Kan bağışı"]], ["Tabelada ne yazıyordu?", "Gölgesinde oturacak çocuklara armağandır", ["Bu ağaç benimdir", "Dokunmayın"]]] },
  { id: "d03", baslik: "Robot Yarışması", resim: "🤖 🏆 👫", ders: "Takım çalışmasında herkesin fikri değerlidir.",
    metin: ["Okulun robot kulübü, il çapında düzenlenen yarışmaya katılacaktı. Takımda Elif, Kaan, Melis ve Yusuf vardı. Görevleri, engelleri aşarak bir topu kaleye götüren bir robot yapmaktı.", "Takım her gün okuldan sonra kulüp odasında toplanıyordu. Masada kablolar, tekerlekler, sensörler ve küçük bir bilgisayar vardı. Elif programlamayı, Yusuf mekanik parçaları, Kaan elektrik devrelerini seviyordu. Melis ise genelde sessizce not alıyor, herkesi dikkatle dinliyordu. İlk hafta robotun iskeletini kurdular ve ona \"Şimşek\" adını verdiler.", "İlk denemelerde robot hep duvara çarptı. Kaan sinirlenip \"Benim yöntemimle yapalım!\" diye bağırdı. Öğretmenleri Selim Bey herkesi masaya oturttu: \"Her biriniz bir fikir söyleyin, sonra en iyisini birlikte seçelim.\"", "Kaan'ın bağırması üzerine odada gergin bir sessizlik oldu. Elif kırılmıştı, Yusuf kollarını kavuşturdu. Melis ise defterini kapattı. O gün kimse kimseyle konuşmadan eve gitti. Ertesi sabah Kaan, okul bahçesinde arkadaşlarını tek tek bulup özür diledi. \"Kazanmayı o kadar istedim ki sizi dinlemeyi unuttum.\" dedi.", "Sessiz Melis, robotun önüne bir mesafe sensörü eklemeyi önerdi. Yusuf tekerlekleri değiştirdi, Elif programı düzenledi. Kaan da bataryayı hafifletmenin yolunu buldu.", "Yarışmadan bir gün önce büyük bir sorun çıktı: Robotun bataryası bitmek üzereydi ve yenisi yarışmaya kadar gelmeyecekti. Herkes umutsuzluğa kapıldı. Kaan gece boyunca düşündü. Sabah, robotun gereksiz ağırlıklarını söküp, motorların daha az enerji harcamasını sağlayan bir yol buldu. Takım ona alkış tuttu.", "Yarışma günü robot engellerin arasından süzülerek topu kaleye götürdü. Takım ikinci oldu. Kupayı alırken Kaan, \"Asıl kazandığımız şey birlikte çalışmayı öğrenmek oldu.\" dedi.", "Okula döndüklerinde müdür, ikincilik kupasını okulun girişindeki vitrine koydu. Kupanın yanına takımın bir fotoğrafını ve kısa bir not astılar: \"Şimşek'i dört farklı fikir yaptı.\" O yıl robot kulübüne katılmak isteyen öğrenci sayısı iki katına çıktı. Melis ise artık kulübün en çok konuşan üyesiydi!"],
    sorular: [["Robot ne yapacaktı?", "Topu kaleye götürecekti", ["Resim çizecekti", "Şarkı söyleyecekti"]], ["İlk denemelerde ne oldu?", "Robot duvara çarptı", ["Robot kazandı", "Robot kayboldu"]], ["Mesafe sensörünü kim önerdi?", "Melis", ["Kaan", "Selim Bey"]], ["Takım kaçıncı oldu?", "İkinci", ["Birinci", "Üçüncü"]]] },
  { id: "d04", baslik: "Dedemin Radyosu", resim: "📻 👴 📱", ders: "Teknoloji değişse de değerli olan paylaşılan anılardır.",
    metin: ["Mert'in dedesinin eski bir radyosu vardı. Tahta kasalı, düğmeleri büyük bir radyo. Mert ona \"Dede, bunu artık kimse kullanmıyor. Telefonda her şey var.\" dedi.", "Radyonun arkasında küçük bir etiket vardı: \"1968, Ankara.\" Mert etiketi okuyunca şaşırdı. \"Dede, bu radyo babamdan bile yaşlı!\" dedi. Dedesi güldü: \"Babam bunu ilk maaşıyla almıştı. O zamanlar evlerde televizyon yoktu. Radyo, dünyaya açılan tek penceremizdi. Akşam haberlerini dinlemek için herkes sessizce etrafına toplanırdı.\"", "Dedesi radyoyu açtı. Cızırtıların arasından eski bir türkü yükseldi. \"Bu radyoyu ilk aldığımızda bütün mahalle evimize toplanırdı. Maçları, haberleri hep birlikte dinlerdik.\" dedi.", "Dedesi anlatmaya devam etti: \"Bayram sabahları radyodan bayram marşları çalardı. Ramazan'da iftar saatini radyodan beklerdik. Bir de çocuk programları vardı; masallar, şarkılar... Ben bütün hafta o programı beklerdim.\" Mert, dedesinin gözlerinin parladığını gördü. Bu eski radyo, aslında bir hatıra kutusuydu.", "Mert telefonunu cebine koydu ve dedesinin yanına oturdu. Dedesi ona radyo frekansını nasıl ayarlayacağını gösterdi. Birlikte bir futbol maçının anlatımını dinlediler. Gol olduğunda ikisi de aynı anda bağırdı.", "O akşam Mert, sosyal bilgiler ödevi için dedesiyle bir röportaj yaptı. Ödevinin başlığı \"Dünden Bugüne İletişim Araçları\" idi. Öğretmeni ödevi çok beğendi ve sınıf panosuna astı.", "Röportaj sırasında Mert dedesine çok soru sordu: Mektup kaç günde gelirdi? Telefon nasıl kullanılırdı? Dedesi, eskiden köydeki tek telefonun muhtarlıkta olduğunu, uzaktaki akrabaları aramak için sıraya girdiklerini anlattı. Mert, bugün cebindeki telefonla dünyanın öbür ucundaki biriyle saniyeler içinde görüntülü konuşabildiğini düşündü.", "O hafta sonundan sonra Mert ve dedesi her cumartesi radyonun başında buluşmaya karar verdiler. Bazen maç dinlediler, bazen eski türküler. Mert artık telefonuyla da dedesine yeni şeyler öğretiyordu. Dedesi ilk kez torununun gönderdiği bir fotoğrafı açabildiğinde ikisi de kahkahalarla güldü. Eski ve yeni, birbirini tamamlıyordu."],
    sorular: [["Dedenin radyosunun kasası neydi?", "Tahta", ["Plastik", "Cam"]], ["Eskiden mahalleli radyo başında ne yapardı?", "Birlikte maç ve haber dinlerdi", ["Dans ederdi", "Film izlerdi"]], ["Mert ödevi için ne yaptı?", "Dedesiyle röportaj", ["Bir radyo satın aldı", "Telefonla film çekti"]], ["Ödevin başlığı neydi?", "Dünden Bugüne İletişim Araçları", ["Benim Telefonum", "Futbolun Tarihi"]]] },
  { id: "d05", baslik: "Kâğıttan Kuşlar", resim: "🕊️ 🏥 💛", ders: "Küçük bir iyilik büyük bir umut olabilir.",
    metin: ["Defne'nin sınıf arkadaşı Arda, uzun süredir hastanedeydi. Sınıf ona bir sürpriz yapmak istedi ama ne yapacaklarını bilemediler.", "Arda sınıfın en neşeli çocuğuydu. Teneffüslerde herkesi oyuna katar, en sıkıcı derste bile bir espri bulurdu. O hastaneye yatınca sınıfın havası değişti. Arda'nın sırası boş kaldı ve kimse oraya oturmak istemedi. Öğretmenleri her sabah yoklamada onun adını okuyor, \"Arda bugün de bizimle değil ama kalbimizde.\" diyordu.", "Defne, kitapta okuduğu bir hikâyeyi hatırladı: Kâğıttan katlanan kuşların umut getirdiğine inanılıyordu. Sınıfa bir öneri getirdi: \"Arda için yüz tane kâğıt kuş katlayalım, her birinin kanadına güzel bir dilek yazalım.\"", "İlk gün kuş katlamak hiç kolay olmadı. Kâğıtlar yırtıldı, kanatlar eğri çıktı. Mert'in kuşu kurbağaya benzediği için herkes güldü. Defne internetten bir video buldu ve adım adım katlamayı arkadaşlarına gösterdi. Üçüncü gün sınıfın neredeyse hepsi kusursuz kuşlar katlıyordu. Kuşların sayısı her teneffüste biraz daha arttı.", "Bir hafta boyunca teneffüslerde kuş katladılar. Kimi \"Çabuk iyileş!\", kimi \"Seni çok özledik!\" yazdı. Öğretmenleri kuşları renkli iplere dizdi.", "Kuşlardan biri diğerlerinden farklıydı. Sınıfın en sessiz öğrencisi Zeynep, altın renkli bir kâğıttan çok küçük bir kuş katlamış, kanadına \"Seninle oynamayı özledim, döndüğünde bana da top atar mısın?\" yazmıştı. Zeynep, Arda'nın onu oyunlara çağıran tek kişi olduğunu söyledi. Öğretmen o kuşu ipin en ucuna, en görünür yere bağladı.", "Kuşlar hastaneye götürüldüğünde Arda'nın gözleri parladı. Yüzlerce rengârenk kuş odanın tavanından sarkıyordu. Birkaç ay sonra Arda iyileşip okula döndüğünde ilk iş Defne'ye sarıldı: \"Her sabah o kuşlara bakıp güç topladım.\"", "Arda'nın okula döndüğü gün sınıf kapıda bir pankartla onu bekledi. Arda ilk teneffüste Zeynep'in yanına gitti ve elindeki topu ona attı: \"Söz verdim ya!\" O günden sonra sınıfta yeni bir gelenek başladı: Hastalanan ya da üzülen her arkadaşa kâğıttan bir kuş ve küçük bir dilek gönderiliyordu."],
    sorular: [["Arda neden okula gelemiyordu?", "Hastanedeydi", ["Tatildeydi", "Taşınmıştı"]], ["Kâğıt kuş fikrini kim buldu?", "Defne", ["Öğretmen", "Arda"]], ["Kaç kuş katlamayı planladılar?", "Yüz", ["On", "Bin"]], ["Arda kuşlardan nasıl etkilendi?", "Güç topladı", ["Sıkıldı", "Korktu"]]] },
  { id: "d06", baslik: "Zor Bir Karar", resim: "⚽ 📚 🤔", ders: "Sorumluluklarımızı yerine getirmek bize güven kazandırır.",
    metin: ["Cumartesi sabahı mahalle takımının maçı vardı. Kerem forvet oynayacaktı. Ama pazartesi sunacağı fen projesini daha bitirmemişti.", "Kerem bütün hafta antrenmanlara gitmişti. Takım ligde ikinciydi ve bu maç şampiyonluk için çok önemliydi. Fen projesi ise bitkilerin ışığa doğru nasıl büyüdüğünü gösteren bir deneydi. Fasulyeleri ekmiş, her gün ölçmüş ama raporu ve posteri hazırlamayı hep sonraya bırakmıştı. Şimdi her şey aynı hafta sonuna sıkışmıştı.", "Maça gidip projeyi pazar günü bitirmeyi düşündü. Fakat pazar günü anneannesinin doğum günüydü ve bütün gün orada olacaklardı. İki şeyi birden yapması imkânsız görünüyordu.", "Kerem bir kâğıda iki seçeneği yazdı: Maça gidersem ne olur, gitmezsem ne olur? Sonra antrenörüne gidip durumu anlattı. Antrenör, \"Sorumluluklarını önemsemen beni çok mutlu etti. Bu maçta yedek kulübesinde ilk yarı seni bekleriz, ikinci yarıya gel.\" dedi.", "Antrenörün yanından çıkarken Kerem kâğıdına yeniden baktı. Sorunun aslında bu hafta sonu değil, daha önceki günlerde başladığını fark etti: Raporu ve posteri hep \"yarın yaparım\" diye ertelemişti. Ertelediği işler birikmiş ve şimdi hepsi aynı güne sıkışmıştı. \"Bu sefer şansım yaver gitti ama her zaman böyle olmayabilir.\" diye düşündü.", "Cumartesi sabahı Kerem saat altıda kalktı. Kahvaltısını hızlıca yapıp masasına oturdu. Fasulyelerin boylarını tabloya yazdı, grafiğini çizdi, posterine fotoğrafları yapıştırdı. Annesi ona sıcak bir süt getirdi ve sonuç bölümünü okuyup birkaç yazım hatasını gösterdi. Saat onda proje bitmişti. Kerem formasını giyip sahaya koştu.", "Kerem sabah erkenden kalkıp projesini bitirdi, ikinci yarıda sahaya çıktı ve bir de gol attı. Pazartesi projesi sınıfta en çok beğenilenlerden biri oldu. Kerem planlı olmanın ne kadar önemli olduğunu öğrenmişti.", "O akşam Kerem odasının duvarına bir haftalık çalışma çizelgesi astı. Her günün bir küçük görevini yazdı: Pazartesi okuma, salı proje, çarşamba antrenman... \"Bir daha işlerimi son güne bırakmayacağım.\" dedi. Babası çizelgeye bakıp gülümsedi: \"İşte bu, attığın golden de güzel bir gol.\""],
    sorular: [["Kerem'in bitirmediği iş neydi?", "Fen projesi", ["Matematik ödevi", "Resim çalışması"]], ["Pazar günü ne vardı?", "Anneannesinin doğum günü", ["Okul gezisi", "Başka bir maç"]], ["Kerem karar vermek için ne yaptı?", "Seçenekleri kâğıda yazdı", ["Yazı tura attı", "Hiç düşünmedi"]], ["Kerem bu olaydan ne öğrendi?", "Planlı olmanın önemini", ["Futbolun gereksiz olduğunu", "Ödevin önemsiz olduğunu"]]] },
  { id: "d07", baslik: "Gökyüzü Gecesi", resim: "🔭 🌌 🏕️", ders: "Merak, keşfetmenin ilk adımıdır.",
    metin: ["Okulun bilim kulübü, şehrin ışıklarından uzak bir köyde gökyüzü gözlemi düzenledi. Duru, hayatında ilk kez teleskopla bakacaktı.", "Gözlem gecesi için bütün sınıf otobüse bindi. Yanlarına sıcak tutan montlar, termoslarda çay ve el fenerleri almışlardı. Öğretmenleri el fenerlerinin üzerine kırmızı kâğıt yapıştırmalarını istedi: \"Kırmızı ışık gözlerimizin karanlığa alışmasını bozmaz.\" Köye vardıklarında hava soğuktu ama kimse bunu umursamadı. Herkes gökyüzüne bakıyordu.", "Hava karardıkça gökyüzü yıldızlarla doldu. Şehirde hiç bu kadar çok yıldız görmemişti. Rehber öğretmen, \"Şehirdeki ışık kirliliği yıldızları görmemizi engelliyor. Burada gökyüzü ne kadar berrak, değil mi?\" dedi.", "Öğretmen yıldız haritasını açtı ve onlara Büyük Ayı takımyıldızını gösterdi. \"Şu yedi parlak yıldız bir kepçeye benziyor. Kepçenin ucundaki iki yıldızı düz bir çizgiyle uzatırsanız Kutup Yıldızı'nı bulursunuz. Eskiden denizciler yönlerini bu yıldızla bulurdu.\" Duru bu bilgiyi hemen defterine yazdı ve parmağıyla gökyüzünde çizgiyi çizdi.", "Teleskobu Ay'a çevirdiler. Duru Ay'ın yüzeyindeki kraterleri gördü. Sonra Satürn'ün halkalarını seçti. Heyecandan sesi titredi: \"Kitapta gördüğümün aynısı!\"", "Gece yarısına doğru gökyüzünde bir ışık çizgisi kaydı. Çocuklar hep birlikte \"Kayan yıldız!\" diye bağırdı. Öğretmen gülümsedi: \"Aslında bu bir yıldız değil. Uzaydan gelen küçük bir taş parçası, atmosfere girince sürtünmeyle yanıyor. Buna göktaşı diyoruz.\" Duru biraz hayal kırıklığına uğradı ama sonra bunun daha da ilginç olduğunu düşündü.", "Eve döndüğünde Duru, odasının ışığını kapattı ve pencereden baktı. Birkaç yıldız seçebildi. Ertesi gün bilim kulübünde, sokak lambalarının ışığını yere yönlendirmeyle ilgili bir proje hazırlamaya karar verdiler.", "Projeyi belediyeye sundular. Belediye, okulun çevresindeki birkaç sokak lambasının başlığını ışığı yalnızca yere vuracak şekilde değiştirdi. Duru her akşam penceresinden bakıp yıldızları saymaya başladı. İlk gün dört yıldız saymıştı; bir ay sonra on bir! Büyüyünce astronom olmaya çoktan karar vermişti."],
    sorular: [["Gözlem nerede yapıldı?", "Şehir ışıklarından uzak bir köyde", ["Okulun çatısında", "Alışveriş merkezinde"]], ["Şehirde yıldızlar neden az görünür?", "Işık kirliliği yüzünden", ["Yıldızlar şehirden kaçtığı için", "Bulut olmadığı için"]], ["Duru teleskopla hangi gezegenin halkalarını gördü?", "Satürn", ["Mars", "Venüs"]], ["Kulüp hangi projeyi hazırlamaya karar verdi?", "Sokak lambalarının ışığını yere yönlendirme", ["Yeni bir teleskop yapma", "Uzay gemisi tasarlama"]]] },
  { id: "d08", baslik: "Şerife Bacı'nın İzinde", resim: "🇹🇷 🐂 ❄️", ders: "Kahramanlarımızın fedakârlığı sayesinde bugün özgürüz.",
    metin: ["Sosyal bilgiler dersinde öğretmen Millî Mücadele'yi anlatıyordu. Konu, cepheye cephane taşıyan kadınlara gelince sınıf sessizleşti.", "Öğretmen tahtaya bir harita çizdi. İnebolu limanından Kastamonu'ya, oradan Ankara'ya uzanan dağlık bir yol gösterdi: \"Bu yola İstiklal Yolu denir. Kurtuluş Savaşı'nda silah ve cephane, gemilerle İnebolu'ya, oradan kağnılarla, at sırtında, hatta insan sırtında cepheye taşındı. Kadınlar, çocuklar, yaşlılar; herkes bu yolda yürüdü.\"", "Öğretmen anlattı: \"Şerife Bacı, kış ortasında İnebolu'dan kağnısıyla cephane taşıyordu. Kar fırtınası çıktı. Şerife Bacı kendi örtüsünü ve battaniyesini cephanenin üstüne örttü ki ıslanmasın. Kendisi soğuktan donarak şehit oldu. Cephane ise kuru bir şekilde yerine ulaştı.\"", "Ayşe kağnıyı hiç görmemişti. Öğretmen anlattı: \"Kağnı, tahta tekerlekli, öküzlerin çektiği bir arabadır. Çok yavaş gider ve gıcırdar. Kışın kar yağdığında tekerlekler çamura saplanırdı. İnsanlar kağnıyı itmek için omuz verir, bazen öküzlerin yerine kendileri koşulurdu.\" Sınıf, bu zorlu yolculuğu gözünün önüne getirmeye çalıştı.", "Ayşe'nin gözleri doldu. \"Öğretmenim, kendini mi düşünmedi?\" diye sordu. Öğretmen, \"O, vatanını kendinden daha çok düşündü.\" dedi.", "O hafta sınıf, Millî Mücadele kahramanları için bir köşe hazırladı. Ayşe, Şerife Bacı'nın kağnısının resmini çizdi ve altına şunu yazdı: \"Senin battaniyen bizim bayrağımız oldu.\"", "Ders bittiğinde Ayşe eve koşup büyükannesine Şerife Bacı'yı anlattı. Büyükannesi duvardaki eski bir fotoğrafı indirdi. Fotoğrafta genç bir kadın vardı: \"Bu benim babaannem. O da o yıllarda köyden cepheye çorap ve ekmek taşırmış.\" Ayşe hayretle fotoğrafa baktı. Tarih kitaplarındaki kahramanlar, aslında kendi ailesinin içindeydi.", "Hazırladıkları köşeyi bütün okul ziyaret etti. Müdür, Ayşe'nin resmini okulun girişine astırdı. Ayşe her sabah o resmin önünden geçerken bir an duruyor ve içinden teşekkür ediyordu. Artık bayram törenlerinde İstiklal Marşı'nı okurken sesi daha gür çıkıyordu; çünkü her kelimesinin bir bedeli olduğunu biliyordu."],
    sorular: [["Şerife Bacı neyle cephane taşıyordu?", "Kağnıyla", ["Trenle", "Kamyonla"]], ["Şerife Bacı hangi şehirden yola çıkmıştı?", "İnebolu", ["İzmir", "Ankara"]], ["Şerife Bacı battaniyesini nereye örttü?", "Cephanenin üstüne", ["Kendi üstüne", "Öküzlerin üstüne"]], ["Sınıf o hafta ne hazırladı?", "Kahramanlar köşesi", ["Kermes", "Tiyatro"]]] },
  { id: "d09", baslik: "Su Damlası Kadar", resim: "💧 🚰 🌍", ders: "Su, korunması gereken sınırlı bir kaynaktır.",
    metin: ["Bir gün okulun musluklarından su akmadı. Bakım yapılıyordu. Öğrenciler sabahtan öğlene kadar ellerini yıkayamadı, su içmek için uzun kuyruklar oluştu.", "Teneffüste herkes şikâyet ediyordu: \"Ellerim yapış yapış oldu!\", \"Çok susadım!\" Kantinin önünde su almak için uzun bir kuyruk oluşmuştu. Ece kuyrukta beklerken, sabah evde dişlerini fırçalarken musluğu açık bıraktığını hatırladı. O zaman su hiç değerli gelmemişti. Şimdi tek bir yudum su için on dakika bekliyordu.", "Fen öğretmeni bu durumu bir derse dönüştürdü. \"Dünyadaki suyun çok küçük bir kısmı içilebilir tatlı sudur. Bugün birkaç saat susuz kalmak bizi zorladı. Bazı ülkelerde insanlar her gün kilometrelerce yürüyerek su taşıyor.\" dedi.", "Öğretmen tahtaya büyük bir daire çizdi: \"Bu daire dünyadaki bütün sular olsun. Bunun neredeyse tamamı denizlerdeki tuzlu sudur. Tatlı suyun büyük kısmı da kutuplarda buz olarak donmuş durumda. İçebileceğimiz su, bu dairenin içinde küçücük bir nokta kadar.\" Tahtaya minicik bir nokta koydu. Sınıf sessizce o noktaya baktı.", "Öğrenciler okulun tuvaletlerini tek tek gezip damlayan muslukları buldular. Her musluğun altına bir bardak koyup bir saat beklediler. Bardaklara ne kadar su biriktiğini ölçtüler ve günlük miktarı hesapladılar. Sonuç onları şaşırttı: Üç musluk birlikte, bir haftada bir sınıfın bütün öğrencilerinin içeceği kadar suyu boşa akıtıyordu.", "Sınıf bir hesaplama yaptı: Damlayan bir musluk günde bir kova su israf edebiliyordu. Okulda üç tane damlayan musluk vardı. Öğrenciler bunu okul müdürüne bildirdi ve musluklar tamir edildi.", "Ece eve dönünce ailesiyle bir \"su tasarrufu sözleşmesi\" hazırladı: Dişler fırçalanırken musluk kapatılacak, bulaşık makinesi tam dolmadan çalıştırılmayacak. Sözleşmeyi buzdolabının kapağına astılar.", "Sözleşmenin ilk haftasının sonunda Ece'nin babası su faturasını gösterdi: Ödedikleri para azalmıştı. Ece sevinçle sınıfa koştu ve diğer arkadaşlarına da sözleşmeyi önerdi. Kısa sürede sınıftaki birçok aile buzdolabına aynı listeyi astı. Öğretmen, \"Bir damla az görünür ama milyonlarca damla bir nehir eder.\" dedi."],
    sorular: [["Musluklardan neden su akmadı?", "Bakım yapılıyordu", ["Su bitmişti", "Kış olduğu için"]], ["Damlayan bir musluk günde ne kadar su israf edebilir?", "Bir kova", ["Bir bardak", "Bir damla"]], ["Öğrenciler damlayan muslukları kime bildirdi?", "Okul müdürüne", ["Belediyeye", "Velilere"]], ["Ece sözleşmeyi nereye astı?", "Buzdolabının kapağına", ["Okul panosuna", "Kapıya"]]] },
  { id: "d10", baslik: "Yeni Komşu", resim: "🏠 🌍 🤝", ders: "Farklı kültürleri tanımak bizi zenginleştirir.",
    metin: ["Can'ların apartmanına yeni bir aile taşındı. Aile Japonya'dan gelmişti. Küçük oğulları Haru, Türkçeyi yeni öğreniyordu.", "Haru'nun ailesi, babası Türkiye'de bir fabrikada mühendis olarak çalışmaya başladığı için gelmişti. Haru ilk günlerde çok çekingendi. Apartmanın merdivenlerinde Can'la karşılaştığında başını hafifçe eğip selam veriyordu. Can bunun Japonların selamlaşma biçimi olduğunu sonradan öğrenecekti. Haru'nun gözleri, yeni bir arkadaş bulma umuduyla parlıyordu.", "Can önce nasıl konuşacağını bilemedi. Sonra Haru'nun elinde bir futbol topu gördü. İkisi bahçede top oynamaya başladı. Kelimelere ihtiyaç kalmamıştı.", "Bir akşam Haru'nun annesi Can'ların ailesini yemeğe davet etti. Masada suşi ve miso çorbası vardı. Can yemek çubuklarıyla yemeye çalıştı, herkes güldü. Ertesi hafta da Can'ın annesi onlara mantı ve baklava ikram etti.", "Okulda Haru'nun sırası Can'ın yanına verildi. İlk günler Can ona tahtadaki kelimeleri parmağıyla gösterip okumasına yardım etti. Haru matematikte çok iyiydi; sayıların dili her yerde aynıydı. Bir problemde Can takılınca Haru ona çözümü kâğıda çizerek anlattı. Öğretmen, \"İkiniz birbirinize çok iyi öğretmenlik yapıyorsunuz.\" dedi.", "Haru, Can'a Japonca \"arigato\" (teşekkür ederim) ve \"konnichiwa\" (merhaba) demeyi öğretti. Can da ona \"afiyet olsun\" ve \"kolay gelsin\" sözlerini öğretti. Haru bu sözlere çok şaşırdı: \"Türkçede birine iş yaparken bile güzel dilek söylüyorsunuz!\" Bir gün Haru, kâğıttan katladığı bir turna kuşunu Can'a armağan etti.", "Zamanla Haru Türkçe kelimeler, Can ise birkaç Japonca kelime öğrendi. Okulda dünya kültürleri haftası düzenlendiğinde ikisi birlikte bir sunum yaptı: \"İki Ülke, Bir Arkadaşlık.\"", "Sunumun sonunda iki arkadaş, sınıfa birer kâğıt turna ve birer lokum dağıttı. Sınıf onları uzun süre alkışladı. Öğretmen, \"Farklı dilleri konuşabiliriz, farklı yemekler yiyebiliriz. Ama dostluğun dili herkes için aynıdır.\" dedi. Can ile Haru o yaz birlikte yüzme kursuna yazıldılar; dostlukları her geçen gün büyüyordu."],
    sorular: [["Yeni aile hangi ülkeden gelmişti?", "Japonya", ["Çin", "İtalya"]], ["Can ve Haru ilk olarak ne yaptı?", "Top oynadı", ["Kitap okudu", "Resim çizdi"]], ["Can'ın annesi ne ikram etti?", "Mantı ve baklava", ["Suşi", "Pizza"]], ["Sunumlarının adı neydi?", "İki Ülke, Bir Arkadaşlık", ["Japon Yemekleri", "Futbolun Tarihi"]]] },
  { id: "d11", baslik: "Mıknatıslı Kurtarma", resim: "🧲 🔑 🕳️", ders: "Öğrendiklerimizi hayatta kullanınca bilgi değer kazanır.",
    metin: ["Bahçede oynarken babaannesinin anahtarı, bahçe kapısının yanındaki dar bir aralığa düştü. Aralık o kadar dardı ki kimsenin eli sığmıyordu.", "Babaanne kapının önünde çaresizce duruyordu. Eve giremezse ilaçlarını alamayacaktı, üstelik akşam yemeği için ocağa koyduğu çorba da içerideydi. Zeynep önce bir çubukla anahtarı itmeyi denedi ama anahtar daha da derine kaydı. Sonra parmaklarını sokmaya çalıştı; aralık çok dardı. \"Acele etmek yerine düşünmeliyim.\" dedi kendi kendine.", "Babaanne üzüldü: \"Yedek anahtarım da yok.\" Zeynep düşündü taşındı. Fen dersinde mıknatısın demiri çektiğini öğrenmişti. Anahtar da demirdendi!", "Zeynep fen dersini hatırladı. Öğretmen sınıfa bir mıknatıs, bir çivi, bir plastik kalem, bir alüminyum kâğıt ve bir ataş getirmişti. Mıknatıs yalnızca çiviyi ve ataşı çekmişti. Öğretmen, \"Mıknatıs demir, nikel ve kobalt gibi metalleri çeker; her metali çekmez.\" demişti. Peki babaannesinin anahtarı demirden miydi?", "Buzdolabının üzerindeki mıknatıslardan birini aldı, bir ipe bağladı. İpi yavaşça aralığa sarkıttı. Birkaç denemeden sonra tık diye bir ses geldi. Anahtar mıknatısa yapışmıştı!", "Zeynep babaannesine anahtarın nasıl bir şey olduğunu sordu. \"Eski, ağır, gri renkli bir anahtar.\" dedi babaanne. Zeynep kendi okul anahtarını çıkarıp buzdolabının mıknatısını ona yaklaştırdı. Anahtar mıknatısa yapışmadı! Çünkü onunki pirinçtendi. Ama babaannesinin eski demir anahtarı çekilebilirdi. Bir deneme yapmaya değerdi.", "Babaannesi Zeynep'i alnından öptü. Akşam Zeynep, olanları fen öğretmenine yazdı. Öğretmeni ertesi gün bu hikâyeyi sınıfa anlattı ve \"Bilimin en güzel yanı, hayatı kolaylaştırmasıdır.\" dedi.", "Ertesi hafta fen dersinde öğretmen, Zeynep'in yöntemini bütün sınıfla denedi. Kum dolu bir kabın içine ataşlar ve küçük çiviler sakladılar; öğrenciler ipe bağlı mıknatıslarla onları çıkarmaya çalıştı. En çok çiviyi bulan grup Zeynep'in grubu oldu. Zeynep o gün, bilginin ancak kullanıldığında gerçek bir güce dönüştüğünü anladı."],
    sorular: [["Anahtar nereye düştü?", "Dar bir aralığa", ["Kuyuya", "Denize"]], ["Zeynep bu bilgiyi nereden öğrenmişti?", "Fen dersinden", ["Televizyondan", "Babaannesinden"]], ["Zeynep mıknatısı neye bağladı?", "İpe", ["Sopaya", "Telefona"]], ["Anahtar neden mıknatısa yapıştı?", "Demirden yapıldığı için", ["Islak olduğu için", "Hafif olduğu için"]]] },
  { id: "d12", baslik: "Sessiz Kütüphane", resim: "📚 🤫 🔇", ders: "Başkalarının hakkına saygı göstermek hepimizin sorumluluğudur.",
    metin: ["Belediyenin halk kütüphanesinde sınav dönemiydi. Masalar ders çalışan gençlerle doluydu. Ali ve kuzeni de ödev için oraya gelmişti.", "Kütüphane, Ali'nin çok sevdiği bir yerdi. Yüksek tavanları, tahta rafları ve kitap kokusuyla bambaşka bir dünyaydı. Çocuk bölümünde renkli minderler, masal kitapları ve küçük bir okuma köşesi vardı. Ali her hafta oradan iki kitap alıyordu. Ama sınav döneminde büyük okuma salonu çok kalabalık ve çok sessiz olurdu.", "Kuzeni telefonundan sesli video açtı ve kahkahalarla gülmeye başladı. Masadaki üniversite öğrencisi bir abla başını kaldırıp iç çekti. Görevli kibarca uyardı.", "Kuzeni Emre ilk kez kütüphaneye geliyordu. Ödevle hiç ilgilenmiyor, sürekli telefonuna bakıyordu. Videoda komik bir kedi vardı ve Emre kahkahasını tutamadı. Salondaki birkaç kişi dönüp baktı. Bir genç kulaklarını elleriyle kapattı. Ali, yüzünün kızardığını hissetti. Sanki herkes ona bakıyordu.", "Ali utandı. Kuzenine fısıldadı: \"Burası herkesin. Herkesin sessizlik hakkı var. Biz yüksek sesle konuşursak onların hakkını yemiş oluruz.\" Kuzeni telefonu kapattı ve özür diledi.", "Görevli abla yanlarına geldi ve fısıltıyla konuştu: \"Burada herkes çalışıyor. Bazıları için bu sınav çok önemli. Telefonu sessize alırsanız çok seviniriz.\" Kızmamıştı, çok nazikti. Emre önce surat astı. Ama Ali'nin söyledikleri onu düşündürdü. Etrafına baktı: Kimi not alıyor, kimi gözlerini kapatıp ezber yapıyordu.", "Çıkışta abla onlara teşekkür etti ve yarın sınavı olduğunu söyledi. Ali eve dönerken kütüphanenin kapısındaki tabelayı hatırladı: \"Sessizlik, başkalarına gösterdiğimiz saygıdır.\"", "Bir hafta sonra Ali ve Emre kütüphaneye yeniden gittiler. Bu kez Emre telefonunu çantasına koydu ve Ali'nin önerdiği bir macera kitabını okudu. Kitabı o kadar sevdi ki ödünç alıp eve götürdü. Kapıdan çıkarken görevli abla onlara gülümsedi. Emre, \"Burası düşündüğümden çok daha güzelmiş.\" dedi."],
    sorular: [["Kütüphanede hangi dönem vardı?", "Sınav dönemi", ["Tatil", "Bayram"]], ["Kuzen ne yaptı?", "Sesli video açtı", ["Kitap çaldı", "Uyudu"]], ["Ali kuzenine ne açıkladı?", "Herkesin sessizlik hakkı olduğunu", ["Videonun komik olmadığını", "Eve gitmeleri gerektiğini"]], ["Tabelada ne yazıyordu?", "Sessizlik, başkalarına gösterdiğimiz saygıdır", ["Yiyecek yasaktır", "Kitapları geri getirin"]]] },
  { id: "d13", baslik: "Erozyonla Savaşan Çocuklar", resim: "⛰️ 🌱 🌧️", ders: "Toprağı korumak geleceğimizi korumaktır.",
    metin: ["Köydeki tepe her yağmurda biraz daha aşınıyordu. Toprak sele kapılıp dereye akıyordu. Tarlalar verimsizleşmişti.", "Köyün en yaşlısı Hatice Nine, çocukken o tepenin meşe ağaçlarıyla kaplı olduğunu anlatırdı. Yıllar içinde ağaçlar odun için kesilmiş, yerlerine yenisi dikilmemişti. Şimdi tepede sadece birkaç cılız çalı kalmıştı. Her yağmurdan sonra tepenin yamacında yeni yarıklar açılıyor, dere kahverengi bir çamur gibi akıyordu. Köylüler buna bir çare bulamıyordu.", "Ziraat mühendisi Leyla Hanım okula geldi. \"Buna erozyon denir. Bitkilerin kökleri toprağı tutar. Tepe çıplak kaldığı için toprak akıp gidiyor.\" dedi.", "Leyla Hanım bir deney de yaptı. İki tepsiye toprak koydu; birine çimen ekilmiş toprak, ötekine çıplak toprak. İkisini eğip üzerlerine sulama kabıyla su döktü. Çıplak topraktan akan su çamur gibiydi, çimenli topraktan akan su ise neredeyse berraktı. Çocuklar gözleriyle görmüşlerdi: Bitkiler toprağın bekçisiydi.", "Öğrenciler hemen harekete geçti. Belediye ve bir çevre vakfı fidan desteği verdi. Bir pazar günü bütün köy tepeye çıktı. Çocuklar fidanları dikti, büyükler sulama arkı kazdı.", "Fidan dikmek kolay değildi. Toprak sertti, çocukların küçük kürekleri zorlanıyordu. Ama herkes birbirine yardım etti. Babalar çukurları açtı, anneler fidanları taşıdı, çocuklar fidanları çukura yerleştirip toprağı bastırdı. Akşam olduğunda tepeye tam beş yüz fidan dikilmişti. Herkes yorgundu ama yüzlerde mutlu bir gülümseme vardı.", "Üç yıl sonra tepe yemyeşil olmuştu. Yağmur yağdığında dere artık çamurlu akmıyordu. Muhtar, fidan diken çocukların isimlerini bir taşa kazıtıp tepeye koydu.", "Taşın üzerinde şu yazı vardı: \"Bu tepeyi geleceğe çocuklarımız emanet etti.\" Çocuklar her bahar tepeye çıkıp ağaçlarını ziyaret etmeye devam etti. Tepede artık kuşlar, tavşanlar ve kelebekler yaşıyordu. Köyün tarlaları yeniden bereketlenmişti. Hatice Nine, \"Çocukluğumdaki tepe geri geldi.\" diyerek sevinç gözyaşları döktü."],
    sorular: [["Tepe neden aşınıyordu?", "Yağmurda toprak akıp gidiyordu", ["Rüzgâr çok sıcaktı", "Hayvanlar kazıyordu"]], ["Toprağı tutan nedir?", "Bitkilerin kökleri", ["Taşlar", "Plastik örtüler"]], ["Fidan desteğini kimler verdi?", "Belediye ve bir çevre vakfı", ["Bir futbol kulübü", "Bir pastane"]], ["Muhtar ne yaptı?", "Çocukların isimlerini taşa kazıttı", ["Tepeyi kapattı", "Çocuklara para verdi"]]] },
  { id: "d14", baslik: "Yarım Kalan Resim", resim: "🎨 🖌️ 🏅", ders: "Hata yapmak öğrenmenin bir parçasıdır.",
    metin: ["Esra, resim yarışması için deniz manzarası çiziyordu. Tam bitirmek üzereyken suluboya kabı devrildi ve resmin yarısı mor bir lekeyle kaplandı.", "Esra o resmi tam bir haftadır çiziyordu. Önce mavi tonlarla denizi, sonra beyaz köpüklü dalgaları ve uzaktaki küçük bir yelkenliyi boyamıştı. Yarışmaya son bir gün kalmıştı. Esra son dokunuşları yapmak için fırçasını mor boyaya batırırken dirseği su kabına çarptı. Mor su, resmin üzerine bir anda yayıldı.", "Esra ağlamaya başladı. Annesi yanına oturdu: \"Bu lekeye bir de başka gözle bak. Sence neye benziyor?\" Esra uzun uzun baktı. Leke, denizin üstünde batan güneşin yansımasına benziyordu.", "Esra önce annesine inanmadı. \"Bu sadece bir leke anne, her şey mahvoldu.\" dedi. Annesi ona ünlü ressamların bile bazen yanlışlıkla döktükleri boyalardan yeni fikirler bulduğunu anlattı. \"Bir resmi yeniden yapmak yerine, hatayı resmin bir parçası yapmayı dene. Bazen en güzel şeyler planlamadığımız anlarda doğar.\"", "Esra fırçasını yeniden eline aldı. Lekeyi mor bir gün batımına dönüştürdü, üstüne martılar çizdi. Resim eskisinden de güzel olmuştu.", "Esra saatlerce çalıştı. Lekenin kenarlarını turuncu ve pembeyle yumuşattı, ufukta batan güneşi çizdi. Denizin üzerine güneşin parlak yansımasını ekledi. Yelkenlinin yelkenini de güneşin ışığıyla pembeye boyadı. Resim bittiğinde geri çekilip baktı. Resim artık sabahki sakin deniz değil, sıcacık bir akşamüstü olmuştu.", "Yarışmada Esra'nın resmi \"En Yaratıcı Eser\" ödülünü kazandı. Esra ödül konuşmasında şöyle dedi: \"Bazen hatalarımız bizi daha güzel bir yere götürür.\"", "Esra o resmi odasının duvarına astı. Ne zaman bir işte hata yapsa ve moralinin bozulduğunu hissetse, o mor gün batımına bakıyordu. Matematik sınavında yanlış yaptığı sorular, kırdığı bir vazo, yarım kalan bir ödev... Her birinin ardından yeniden başlamanın mümkün olduğunu o resim ona hatırlatıyordu."],
    sorular: [["Esra ne çiziyordu?", "Deniz manzarası", ["Orman", "Şehir"]], ["Resme ne oldu?", "Suluboya devrildi", ["Yırtıldı", "Kayboldu"]], ["Leke neye dönüştü?", "Gün batımına", ["Gemiye", "Balığa"]], ["Esra hangi ödülü aldı?", "En Yaratıcı Eser", ["En Hızlı Ressam", "Katılım Belgesi"]]] },
  { id: "d15", baslik: "Market Fişi", resim: "🧾 🛒 🔍", ders: "Bilinçli tüketici haklarını bilir ve kullanır.",
    metin: ["Murat, annesiyle markete gitti. Kasada ödeme yaptıktan sonra annesi fişi dikkatle inceledi. Murat, \"Anne, fişe neden bakıyorsun?\" diye sordu.", "Kasada sıra uzundu ve kasiyer çok hızlı çalışıyordu. Murat'ın annesi poşetleri doldururken bir yandan da kasanın ekranındaki fiyatlara bakıyordu. Ödemeyi yaptıktan sonra kasadan ayrılmadan önce fişi aldı ve satır satır okudu. Murat sabırsızlandı: \"Anne, hadi gidelim, dondurmalar eriyecek!\"", "Annesi fişi gösterdi: \"Bak, makarnayı iki kez okutmuşlar. Fişe bakmasaydık fazla para ödemiş olacaktık.\" Kasiyer hatasını fark edip özür diledi ve fazla parayı geri verdi.", "Kasiyer abla gerçekten çok mahcup oldu. \"Çok yoğunuz, bazen ürün iki kez geçebiliyor. Kontrol ettiğiniz için teşekkür ederim.\" dedi. Fazla ödenen parayı geri verdi. Murat şaşırmıştı; küçük bir kâğıt parçası, fazla ödenecek parayı geri kazandırmıştı. Annesi, \"Fiş sadece bir kâğıt değil, alışverişimizin belgesidir.\" dedi.", "Eve dönerken annesi Murat'a, aldıkları sütün son kullanma tarihine baktırdı. \"Bilinçli bir tüketici; fişini alır, tarihleri kontrol eder, ihtiyacı kadar alışveriş yapar.\" dedi.", "Eve gelince annesi Murat'a bir oyun önerdi. Mutfaktaki ürünlerin üzerindeki son kullanma tarihlerine birlikte baktılar. Rafın arkasında, tarihi geçmek üzere olan bir yoğurt buldular. \"İşte bu yüzden yeni aldıklarımızı arkaya, eskileri öne koymalıyız.\" dedi annesi. Murat buzdolabını yeniden düzenledi.", "Ertesi hafta okulda harçlıkla alışveriş etkinliği yapıldı. Murat ürünleri alırken önce fiyat etiketlerine baktı, fişini istedi. Öğretmeni onu \"Haftanın Bilinçli Tüketicisi\" seçti.", "Murat o günden sonra harçlığını harcarken de dikkatli oldu. Bir şeyi almadan önce \"Buna gerçekten ihtiyacım var mı?\" diye düşünüyordu. Ay sonunda biriktirdiği parayla uzun zamandır istediği kitabı aldı. Kitabın fişini de defterine yapıştırdı. Artık o da annesi gibi bilinçli bir tüketiciydi."],
    sorular: [["Fişte hangi hata vardı?", "Makarna iki kez okutulmuştu", ["Süt eksikti", "Fiyatlar düşüktü"]], ["Kasiyer ne yaptı?", "Özür diledi, parayı geri verdi", ["Kızdı", "Marketi kapattı"]], ["Annesi sütün neyine baktırdı?", "Son kullanma tarihine", ["Rengine", "Kokusuna"]], ["Murat hangi unvanı aldı?", "Haftanın Bilinçli Tüketicisi", ["Sınıf Başkanı", "En İyi Kasiyer"]]] },
  { id: "d16", baslik: "Deprem Çantası", resim: "🎒 🔦 🚨", ders: "Afetlere hazırlıklı olmak hayat kurtarır.",
    metin: ["Hayat bilgisinde başlayan konu, Sena'nın aklından çıkmıyordu: Deprem ülkesinde yaşıyorduk ve hazırlıklı olmalıydık. Akşam ailesine bir öneride bulundu: \"Hadi bir deprem çantası hazırlayalım.\"", "Sena'nın babası önce biraz şaşırdı ama sonra kızının haklı olduğunu kabul etti. \"Ülkemiz deprem kuşağında. Önemli olan korkmak değil, hazırlıklı olmak.\" dedi. Akşam yemeğinden sonra bütün aile masanın etrafında toplandı. Sena okulda aldığı notları okudu ve neler yapmaları gerektiğini birlikte konuştular.", "Babası listeyi yazdı: Su, uzun süre dayanan yiyecekler, el feneri, yedek pil, düdük, ilk yardım malzemeleri, battaniye ve önemli belgelerin fotokopileri. Sena her birini tek tek çantaya yerleştirdi.", "Çantayı hazırlarken küçük kardeşi Efe de yardım etmek istedi. Efe çantaya en sevdiği oyuncak arabayı koymak istedi. Sena gülümsedi ve ona, çantanın içindekilerin zor bir anda hayat kurtarabileceğini anlattı. Ama Efe'nin çok korkabileceğini düşünerek çantaya küçük bir boyama kitabı ve birkaç kalem koymasına izin verdi.", "Sonra evdeki dolapları duvara sabitlediler. Ailece bir toplanma noktası belirlediler: Evin yakınındaki parkın büyük kapısı. Sena kardeşine \"Çök, kapan, tutun\" hareketini gösterdi.", "Sena'nın babası çantanın her altı ayda bir kontrol edilmesi gerektiğini söyledi. Suyun ve yiyeceklerin son kullanma tarihlerine bakılacak, pillerin çalışıp çalışmadığı denenecekti. Sena bunu takvime işaretledi. Aile, deprem olduğunda telefonlar çekmezse diye şehir dışında yaşayan dayılarını \"haber verilecek kişi\" olarak belirledi.", "Birkaç hafta sonra okulda deprem tatbikatı yapıldığında Sena çok sakin davrandı. Öğretmeni onun hazırlığını sınıfa örnek gösterdi ve herkesin evinde bir deprem çantası olması için ödev verdi.", "Ertesi hafta Sena'nın sınıfındaki öğrencilerin çoğu evlerinde deprem çantası hazırladıklarını anlattılar. Bazıları çantalarının fotoğrafını getirdi. Öğretmen, \"Bilgi paylaşıldıkça çoğalır. Siz bu bilgiyi ailelerinize taşıdınız, belki onlar da komşularına anlatır.\" dedi. Sena, küçük bir fikrin nasıl yayıldığını görünce çok mutlu oldu."],
    sorular: [["Deprem çantasında hangisi yoktu?", "Oyun konsolu", ["El feneri", "Düdük"]], ["Dolaplara ne yapıldı?", "Duvara sabitlendi", ["Boyandı", "Satıldı"]], ["Ailenin toplanma noktası neresiydi?", "Parkın büyük kapısı", ["Okulun bahçesi", "Evin çatısı"]], ["Deprem anında yapılan hareket nedir?", "Çök, kapan, tutun", ["Koş, bağır, saklan", "Atla, zıpla, dön"]]] },
  { id: "d17", baslik: "Ödünç Kitap", resim: "📕 ⏰ 🤝", ders: "Ödünç aldığımız şeylere kendi eşyamızdan daha çok özen gösteririz.",
    metin: ["Berk, arkadaşı Nil'den macera kitabını ödünç aldı. \"Bir haftada geri getiririm.\" diye söz verdi. Ama kitap o kadar sürükleyiciydi ki iki günde bitirdi.", "Kitap, uzak bir adada kaybolan iki kardeşin hikâyesini anlatıyordu. Berk her gece yatağında el feneriyle okuyor, bir sonraki sayfada ne olacağını merak ediyordu. Bir gece annesi odasına geldiğinde Berk hâlâ okuyordu. \"Bu kitap çok güzel anne, bırakamıyorum!\" dedi. Annesi gülümsedi ve sadece bir bölüm daha okumasına izin verdi.", "Kitabı çantasında taşırken üzerine meyve suyu döküldü. Sayfaların kenarları dalgalandı. Berk ne yapacağını bilemedi. Belki Nil fark etmezdi.", "Berk eve gelince kitabı kurutmaya çalıştı. Sayfaları tek tek ayırdı, saç kurutma makinesiyle kuruttu, üzerine ağır kitaplar koydu. Ama sayfalar yine de kıvrık ve lekeli kaldı. Kapakta da turuncu bir leke vardı. Berk bütün gece düşündü. İçinden bir ses, \"Söyleme, belki fark etmez.\" diyordu.", "Sonra Nil'in yüzünü düşündü. O kitabı doğum gününde dedesi hediye etmişti. Berk harçlığını biriktirerek aynı kitaptan yenisini aldı. Eski kitabı da yanına koydu.", "Yeni kitabı almak kolay olmadı. Kitap biraz pahalıydı ve Berk'in harçlığı yetmiyordu. Annesine durumu anlattı. Annesi ona yardım etmek yerine bir öneride bulundu: \"Bu hafta evdeki bazı işlere yardım edersen sana ek harçlık verebilirim.\" Berk bulaşıkları kaldırdı, çiçekleri suladı, odasını topladı. Hafta sonunda kitabın parası tamamlanmıştı.", "Nil'e iki kitabı birlikte uzattı ve olanları anlattı. Nil gülümsedi: \"Bana dürüst davrandığın için teşekkür ederim. Eski kitabı da saklayacağım, o artık bir anı.\" İkisinin arkadaşlığı daha da güçlendi.", "O günden sonra Berk ve Nil birbirlerine sık sık kitap ödünç vermeye başladılar. Berk ödünç aldığı her kitabı bir poşete koyarak taşıyordu. Bir gün Nil de Berk'in kitabını yanlışlıkla yırttı ve hemen söyledi. Berk, \"Bana dürüst davrandığın için teşekkür ederim.\" dedi. İkisi de bu cümleyi duyunca güldüler."],
    sorular: [["Berk kitabı ne kadar sürede bitirdi?", "İki günde", ["Bir haftada", "Bir ayda"]], ["Kitaba ne oldu?", "Üzerine meyve suyu döküldü", ["Yırtıldı", "Kayboldu"]], ["Kitap Nil'e kimin hediyesiydi?", "Dedesinin", ["Öğretmeninin", "Berk'in"]], ["Berk sorunu nasıl çözdü?", "Harçlığıyla yeni kitap aldı", ["Hiçbir şey söylemedi", "Kitabı sakladı"]]] },
  { id: "d18", baslik: "Sesin Yolculuğu", resim: "🔊 🎻 👂", ders: "Bilimsel merak günlük olayları anlamamızı sağlar.",
    metin: ["Müzik dersinde öğretmen bir gitarın teline vurdu. Tel titredi ve ses çıktı. Kerem, \"Öğretmenim, ses havada nasıl ilerliyor?\" diye sordu.", "Öğretmen sınıfa bir deney daha yaptı. Bir tahta masanın bir ucuna kalemle hafifçe vurdu. Öğrencilerden biri kulağını masanın öbür ucuna dayadı. Vuruşun sesi, kulağını masaya dayayınca havadan duyduğundan çok daha güçlü geliyordu. \"Demek ki ses katı maddelerde daha iyi ilerliyor!\" dedi Kerem heyecanla.", "Öğretmen, iki karton bardağı uzun bir iple birbirine bağladı. Bir ucu Kerem'e, diğer ucu sınıfın öbür köşesindeki Aslı'ya verdi. Aslı fısıldadı, Kerem sesini net duydu.", "Aslı, bardak telefonuyla bir fıkra anlattı ve Kerem sınıfın öbür ucunda kahkahalarla güldü. Herkes sırayla denemek istedi. Öğretmen, ipin ortasından birine dokunmasını istedi. İpe dokunulunca ses kesildi! Sınıf çok şaşırdı. Öğretmen, \"İpi tuttuğumuzda titreşimi durdurduk. Titreşim yoksa ses de yoktur.\" dedi.", "Öğretmen açıkladı: \"Ses titreşimle oluşur. Bu titreşimler havada, suda ve katı maddelerde yayılır. İp gergin olduğunda titreşimi kolayca taşır.\"", "Öğretmen ayrıca uzayda ses olmadığını anlattı: \"Uzayda hava yoktur. Titreşimi taşıyacak bir madde olmadığı için ses yayılamaz. Astronotlar birbirleriyle telsizle konuşur.\" Kerem bunu duyunca çok şaşırdı. Filmlerde uzay gemileri hep gürültüyle patlıyordu. Demek ki gerçekte uzaydaki bir patlama sessiz olurdu!", "Kerem eve dönünce kardeşiyle kendi bardak telefonunu yaptı. Bu sefer ipi gevşek bıraktılar, ses neredeyse hiç gelmedi. Ertesi gün bu keşfini sınıfa anlattı ve öğretmeninden tam puan aldı.", "Kerem o hafta bütün evi bir ses laboratuvarına çevirdi. Su dolu bardaklara kaşıkla vurup farklı notalar çıkardı; az su ince, çok su kalın ses veriyordu. Kardeşiyle birlikte bardaklardan küçük bir orkestra kurdular. Babası, \"Bu evde bilim de var, müzik de!\" diyerek onları alkışladı."],
    sorular: [["Ses nasıl oluşur?", "Titreşimle", ["Işıkla", "Isıyla"]], ["Öğretmen deney için ne kullandı?", "İki karton bardak ve ip", ["İki ayna", "Bir mıknatıs"]], ["İp gevşek olduğunda ne oldu?", "Ses neredeyse hiç gelmedi", ["Ses daha yüksek geldi", "Ses değişmedi"]], ["Ses hangi ortamlarda yayılır?", "Hava, su ve katılarda", ["Sadece havada", "Sadece suda"]]] },
  { id: "d19", baslik: "Bayramlık Ayakkabılar", resim: "👟 🎁 💝", ders: "Paylaşmanın mutluluğu almanın mutluluğundan büyüktür.",
    metin: ["Bayram yaklaşıyordu. Kübra yeni ayakkabılarını giymek için sabırsızlanıyordu. Mahalle camisinin önünde ayakkabıları yırtık bir çocuk gördü.", "Çocuk, caminin avlusundaki bankta tek başına oturuyordu. Ayakkabılarının burnu yırtılmış, parmakları neredeyse dışarı çıkmıştı. Kübra ona bakarken kendi yeni ayakkabılarını düşündü. Kutusu yatağının altında bekliyordu ve bayram sabahını sabırsızlıkla bekliyordu. Çocuk Kübra'nın kendisine baktığını görünce ayaklarını bankın altına sakladı.", "Eve gelince annesine anlattı. Annesi ona bir soru sordu: \"Senin dolabında hiç giymediğin ama ayağına uyan bir çift ayakkabı yok mu?\" Kübra'nın aklına geçen yıl aldıkları ama biraz büyük geldiği için az giydiği ayakkabıları geldi.", "Kübra eski ayakkabılarını dolaptan çıkardığında biraz tereddüt etti. O ayakkabıları da çok seviyordu; üzerlerinde küçük yıldızlar vardı. Ama sonra o çocuğun ayaklarını bankın altına saklayışını hatırladı. Annesi, \"Sevdiğin bir şeyi vermek, sevmediğin bir şeyi vermekten daha değerlidir.\" dedi. Kübra kararını verdi.", "Ayakkabıları güzelce temizledi, bir kutuya koydu ve üstüne bir kart yazdı: \"İyi bayramlar, arkadaşım.\" Annesiyle birlikte kutuyu mahalle muhtarlığındaki yardımlaşma köşesine bıraktılar.", "Muhtarlıktaki yardımlaşma köşesinde başka eşyalar da vardı: kışlık montlar, okul çantaları, oyuncaklar ve kitaplar. Mahalleli ihtiyaç sahiplerinin onurunu korumak için eşyaları isim vermeden bırakıyor, muhtar da bunları sessizce ihtiyacı olanlara ulaştırıyordu. Kübra, \"Ne güzel, kimse kimseyi mahcup etmiyor.\" diye düşündü.", "Bayram sabahı Kübra, aynı çocuğu kendi ayakkabılarıyla oyun oynarken gördü. Çocuk çok mutluydu. Kübra o an, bayramın asıl anlamının paylaşmak olduğunu anladı.", "Bayram günü akşamı Kübra, ailesiyle büyükannesinin evine gitti. Büyükannesi ona bayram harçlığı verirken Kübra, harçlığının bir kısmını yardımlaşma köşesi için ayırmak istediğini söyledi. Büyükannesi gözleri dolarak torununu öptü: \"Sen bayramı gerçekten anlamışsın kızım.\" O bayram, Kübra'nın hayatındaki en güzel bayram oldu."],
    sorular: [["Kübra çocuğu nerede gördü?", "Caminin önünde", ["Okulda", "Markette"]], ["Kübra çocuğa ne verdi?", "Az giydiği ayakkabılarını", ["Yeni ayakkabılarını", "Para"]], ["Kutuyu nereye bıraktılar?", "Muhtarlıktaki yardımlaşma köşesine", ["Çocuğun kapısına", "Okula"]], ["Kübra bayramın anlamını nasıl yorumladı?", "Paylaşmak", ["Yeni kıyafet giymek", "Şeker toplamak"]]] },
  { id: "d20", baslik: "Şifreli Mesaj", resim: "🔐 💻 ⚠️", ders: "İnternette kişisel bilgilerimizi korumalıyız.",
    metin: ["Emir'in çok sevdiği oyunda bir mesaj belirdi: \"Tebrikler! Ücretsiz 1000 elmas kazandın! Hemen kullanıcı adını, şifreni ve ev adresini yaz.\"", "Mesajın yanında parlayan bir hediye kutusu ve hızla geri sayan bir saat vardı: \"Teklif 5 dakika içinde sona erecek!\" Emir'in kalbi hızla çarpıyordu. Bin elmasla oyundaki en güçlü kılıcı alabilir, arkadaşlarının hepsini geçebilirdi. Parmakları klavyeye gitti. Kullanıcı adını yazmaya başladı bile.", "Emir çok heyecanlandı. Tam yazacakken bilişim dersinde öğrendiklerini hatırladı: Gerçek şirketler asla şifre istemezdi. Bu bir tuzak olabilirdi.", "Emir bilişim öğretmeninin anlattıklarını tek tek hatırladı: Tuzak mesajlar insanları acele ettirirdi; \"hemen\", \"son fırsat\" gibi kelimeler kullanırdı. Gerçek olamayacak kadar iyi teklifler verirdi. Ayrıca bir oyunun ev adresine neden ihtiyacı olsundu ki? Emir yazdığı her şeyi sildi ve bilgisayarın başından kalktı.", "Ekranın fotoğrafını alıp ablasına gösterdi. Ablası mesajın sahte olduğunu, bilgileri çalmak için gönderildiğini söyledi. Birlikte mesajı oyunun destek ekibine bildirdiler ve Emir şifresini değiştirdi.", "Ablası Emir'e, bu tür sahte mesajlara \"oltalama\" dendiğini anlattı. \"Tıpkı balık tutar gibi. Yemi atıyorlar, kim takılırsa bilgilerini çalıyorlar. Şifren onların eline geçseydi, hesabını ele geçirip oyundaki her şeyini alabilirlerdi. Adresin de yabancıların eline geçmemeli.\" Emir az kalsın nasıl bir tuzağa düştüğünü anlayınca ürperdi.", "Ertesi gün Emir sınıfta bu olayı anlattı. Öğretmeni tahtaya üç kural yazdı: \"Şifreni kimseyle paylaşma. Tanımadığın kişilere bilgi verme. Şüphelendiğinde bir büyüğüne danış.\"", "Emir o akşam ailesiyle birlikte bütün hesaplarının şifrelerini güçlü şifrelerle değiştirdi. Ablası ona harf, rakam ve işaretlerden oluşan, kimsenin tahmin edemeyeceği şifreler oluşturmayı öğretti. Emir sınıf panosuna bir afiş de hazırladı: \"Bedava elmas yoktur! Şifre senin, kimseye verme.\""],
    sorular: [["Mesajda ne vaat ediliyordu?", "Ücretsiz 1000 elmas", ["Yeni bir telefon", "Tatil"]], ["Mesaj hangi bilgileri istiyordu?", "Şifre ve adres", ["En sevdiği renk", "Okul notları"]], ["Emir kime danıştı?", "Ablasına", ["Arkadaşına", "Kimseye"]], ["Öğretmenin kurallarından biri hangisidir?", "Şifreni kimseyle paylaşma", ["Her mesaja cevap ver", "Adresini oyunda yaz"]]] },
  { id: "d21", baslik: "Vefalı Dost", resim: "🐕 👴 💛", ders: "Vefa, iyiliği unutmamaktır.",
    metin: ["Sahil kasabasında yaşayan balıkçı Hasan Amca, yıllar önce yaralı bir köpek yavrusu bulmuş, onu tedavi edip büyütmüştü. Köpeğin adını Liman koymuştu.", "Liman, kahverengi tüylü, bir kulağı dik, bir kulağı yatık sevimli bir köpekti. Hasan Amca onu bulduğunda bir ayağı yaralıydı ve sahildeki kayaların arasında titriyordu. Hasan Amca onu evine götürmüş, yarasını sarmış, sıcak bir yatak hazırlamıştı. Liman iyileşince hiç evden ayrılmamış, Hasan Amca'nın gölgesi olmuştu.", "Liman her sabah Hasan Amca'yla iskeleye gider, tekneye binmeden önce onun yanında beklerdi. Akşam tekne dönerken ilk onu iskelede görürlerdi.", "Kasabanın çocukları Liman'ı çok severdi. Okuldan dönerken iskeleye uğrar, onunla top oynarlardı. Liman, Hasan Amca'nın teknesinin motor sesini uzaktan tanırdı. Tekne daha görünmeden kulaklarını dikip kuyruğunu sallamaya başlardı. Balıkçılar, \"Liman'a bakıp Hasan Amca'nın döndüğünü anlarız.\" derdi.", "Bir kış günü Hasan Amca hastalanıp hastaneye kaldırıldı. Liman her akşam iskeleye gidip denize baktı, teknenin gelmesini bekledi. Mahalleli ona yemek getirdi ama o yine de bekledi.", "Günler haftalara dönüştü. Soğuk ve rüzgârlı akşamlarda bile Liman iskelenin ucunda oturup denize bakıyordu. Bakkal Mustafa Amca ona eski bir battaniye serdi. Çocuklar sırayla mama ve su getirdi. Hatta küçük bir kulübe yapıp iskelenin yanına koydular. Ama Liman kulübeye girmiyor, gözünü denizden ayırmıyordu.", "Hasan Amca iyileşip döndüğünde Liman sevinçten havlayarak koşup ona sarıldı. Kasabanın çocukları bu hikâyeyi okul gazetesinde \"Vefalı Dost\" başlığıyla yayımladı.", "Hasan Amca o günden sonra Liman'ı teknesine de almaya başladı. Liman teknenin burnunda oturup rüzgârda kulakları uçuşarak denizi seyrediyordu. Kasabanın çocukları da Liman'dan çok şey öğrendi: Sevgi, emek vermekle büyür; gerçek dostlar zor günlerde de yanında olur."],
    sorular: [["Hasan Amca'nın mesleği neydi?", "Balıkçı", ["Öğretmen", "Doktor"]], ["Köpeğin adı neydi?", "Liman", ["Karabaş", "Deniz"]], ["Hasan Amca hastalanınca Liman ne yaptı?", "Her akşam iskelede bekledi", ["Kasabadan kaçtı", "Başka eve gitti"]], ["Hikâye nerede yayımlandı?", "Okul gazetesinde", ["Televizyonda", "Bir kitapta"]]] },
  { id: "d22", baslik: "Atık Pil Kahramanları", resim: "🔋 ♻️ 🏆", ders: "Küçük adımlar büyük çevre sorunlarını çözebilir.",
    metin: ["Fen dersinde öğretmen, tek bir atık pilin binlerce litre suyu kirletebileceğini anlattı. Sınıf çok şaşırdı. Evlerde biten piller hep çöpe atılıyordu.", "Öğretmen sınıfa bir pilin içini gösteren bir resim getirdi. \"Pillerin içinde cıva, kurşun, kadmiyum gibi zararlı maddeler vardır. Çöpe atılan pil toprağa karışır, yağmurla birlikte yer altı sularına ulaşır. O su da bitkilere, hayvanlara ve sonunda bize ulaşır.\" dedi. Öğrenciler kendi evlerinde kaç pil olduğunu saymaya karar verdi.", "Öğrenciler \"Atık Pil Kahramanları\" adlı bir kampanya başlattı. Okulun girişine büyük bir toplama kutusu koydular, afişler hazırladılar, sınıf sınıf dolaşıp anlattılar.", "Kampanyanın ilk haftasında kutuya sadece birkaç pil atıldı. Öğrenciler hayal kırıklığına uğradı. Sonra bir fikir buldular: Her sınıfın topladığı pil sayısını gösteren bir çizelge hazırlayıp okulun girişine astılar. Sınıflar arasında küçük bir yarış başladı. Bir hafta içinde kutu ağzına kadar doldu ve ikinci bir kutu getirmek gerekti.", "Mahalledeki marketlerle de konuştular. Market sahipleri kasaların yanına küçük toplama kutuları koymayı kabul etti. Kampanya bir ayda tüm mahalleye yayıldı.", "Öğrenciler bir de video hazırladılar. Videoda bir pilin toprağa nasıl zarar verdiğini kartondan yaptıkları maketlerle anlattılar. Okulun müdürü videoyu okulun internet sitesinde paylaştı. Velilerden de destek geldi: Bazı veliler işyerlerine de toplama kutuları koydu. Kampanya, okulun duvarlarını aşmıştı.", "Dönem sonunda toplanan piller tartıldı: Tam kırk iki kilogram! İlçe milli eğitim müdürlüğü okula çevre ödülü verdi. Öğrenciler ödülü aldıklarında aynı cümleyi söylediler: \"Doğa bize emanet.\"", "Toplanan piller, belediyenin anlaşmalı olduğu bir geri dönüşüm tesisine gönderildi. Öğrencilere tesisten bir teşekkür mektubu geldi. Mektupta, pillerdeki bazı metallerin yeniden kullanılabildiği yazıyordu. Öğrenciler kampanyayı her yıl tekrarlamaya karar verdiler. Kutunun üzerine de büyük harflerle şunu yazdılar: \"Pilini at, doğayı kurtar!\""],
    sorular: [["Tek bir atık pil neye zarar verebilir?", "Binlerce litre suya", ["Sadece bir bardak suya", "Hiçbir şeye"]], ["Kampanyanın adı neydi?", "Atık Pil Kahramanları", ["Temiz Okul", "Yeşil Sınıf"]], ["Toplama kutuları başka nereye konuldu?", "Mahalledeki marketlere", ["Parklara", "Hastanelere"]], ["Kaç kilogram pil toplandı?", "Kırk iki", ["Dört", "Dört yüz"]]] },
  { id: "d23", baslik: "Mehmetçik'e Mektup", resim: "✉️ 🇹🇷 🪖", ders: "Vatanımızı koruyanlara minnet duyarız.",
    metin: ["Öğretmen, sınıfa sınırda görev yapan askerlere mektup yazacaklarını söyledi. Ahmet önce ne yazacağını bilemedi. Hiç tanımadığı birine ne söyleyebilirdi?", "Ahmet sınıfın penceresinden dışarı baktı. Okul bahçesinde arkadaşları özgürce koşuyor, bayrak direğindeki bayrak rüzgârda dalgalanıyordu. Babası ona, dedesinin de yıllar önce askerlik yaptığını ve dağlarda kar altında nöbet tuttuğunu anlatmıştı. Ahmet, şu an da birilerinin karda, soğukta nöbet tuttuğunu düşündü.", "Sonra her gece rahatça uyuyabildiğini, sabah güvenle okula gelebildiğini düşündü. Kalemini aldı ve yazmaya başladı: \"Sevgili Mehmetçik, ben her gece huzurla uyuyorum çünkü sen uyanıksın.\"", "Ahmet mektubuna şunları da ekledi: \"Sana çok soğuk olup olmadığını sormak istiyorum. Annem dedi ki nöbette sıcak çay çok iyi gelirmiş. Keşke sana bir termos çay gönderebilseydim. Ben büyüyünce doktor olmak istiyorum. Sen de büyük bir kahramansın.\" Mektubu yazarken birkaç kelimeyi silip yeniden yazdı, en güzel el yazısıyla.", "Mektubuna sınıflarını, en sevdiği dersi ve futbol takımını anlattı. Sonunda bir bayrak resmi çizdi. Bütün mektuplar bir kutuya konup gönderildi.", "Sınıftaki diğer arkadaşları da mektuplarını özenle hazırladı. Elif şiir yazdı, Mert bir futbol topu çizdi, Zeynep annesinin tarifiyle kurabiye yapıp mektubuna bir kurabiye resmi ekledi. Öğretmen bütün mektupları tek tek okudu ve gözleri doldu. \"Bu mektuplar, bir askerin yorgun bir gününü aydınlatacak.\" dedi.", "Bir ay sonra okula bir zarf geldi. İçinde askerlerden bir teşekkür mektubu ve sınırda çekilmiş bir fotoğraf vardı. Fotoğrafta askerlerin elinde çocukların bayrak resimleri vardı. Ahmet o fotoğrafı hiç unutmayacaktı.", "Öğretmen askerlerden gelen fotoğrafı sınıfın en görünür yerine astı. Ahmet her sabah o fotoğrafa bakıp sınıfına giriyordu. Asker mektubunda, \"Sizin çizdiğiniz bayrakları nöbet kulübemizin duvarına astık. Her baktığımızda sizi düşüneceğiz.\" yazmıştı. Ahmet, iki satırlık bir mektubun bile ne kadar büyük bir bağ kurabileceğini öğrenmişti."],
    sorular: [["Mektuplar kime yazıldı?", "Sınırdaki askerlere", ["Başka bir okula", "Belediye başkanına"]], ["Ahmet mektubunun sonuna ne çizdi?", "Bayrak resmi", ["Futbol topu", "Ev resmi"]], ["Okula ne kadar sonra cevap geldi?", "Bir ay sonra", ["Bir gün sonra", "Bir yıl sonra"]], ["Fotoğrafta askerlerin elinde ne vardı?", "Çocukların bayrak resimleri", ["Futbol topu", "Çiçekler"]]] },
  { id: "d24", baslik: "Kendi Bahçemiz", resim: "🥕 🌻 👩‍🌾", ders: "Emek verdiğimiz şeyin değerini daha iyi anlarız.",
    metin: ["Okulun arka bahçesinde boş bir alan vardı. Sınıf, burayı bir sebze bahçesine dönüştürmeye karar verdi. Her öğrenciye küçük bir bölüm düştü.", "Bahçeyi hazırlamak için önce boş alandaki taşları ve çöpleri temizlediler. Okulun hizmetlisi Kemal Amca, onlara toprağı nasıl çapalayacaklarını gösterdi. \"Toprak nefes almalı, havalandırılmalı.\" dedi. Öğretmen her öğrencinin küçük bölümüne adını yazdığı bir tahta levha çaktı. Batuhan'ın bölümüne havuç ve domates ekilecekti.", "Toprağı çapaladılar, tohumları ektiler. Sulamak için bir nöbet listesi hazırladılar. Bazı tohumlar filizlenmedi, bazı fideleri salyangozlar yedi. Ama öğrenciler pes etmedi.", "Bir sabah öğrenciler bahçeye geldiklerinde fidelerin bir kısmının yaprakları delik deşik olmuştu. Salyangozlar gece boyunca ziyafet çekmişti! Öğrenciler üzüldü ama hemen araştırmaya başladılar. Fidelerin etrafına yumurta kabuğu kırıntıları serptiler; salyangozlar sivri kabukların üzerinden geçmeyi sevmiyordu. Kısa sürede fideler toparlandı.", "Haziran geldiğinde bahçede domatesler kızardı, havuçlar topraktan çıktı, ayçiçekleri güneşe döndü. Öğrenciler topladıkları sebzelerle okul kantininde bir salata günü düzenledi.", "Yaz tatili yaklaşırken öğrenciler bir sorunla karşılaştı: Okul kapanınca bahçeyi kim sulayacaktı? Bir aile toplantısı yapıldı. Her hafta iki aile sırayla okula gelip bahçeyi sulamayı kabul etti. Kemal Amca da yardım edeceğini söyledi. Böylece bahçe yaz boyunca da bakımsız kalmayacaktı.", "O gün Batuhan, ilk defa havuç yediğini söyledi. \"Kendi yetiştirdiğim olunca tadı bambaşka oldu.\" dedi. Öğretmenleri gülümsedi: \"Emeğin tadı işte böyledir.\"", "Bahçeden kalan tohumlar özenle kurutuldu ve küçük kese kâğıtlarına konuldu. Her öğrenci bir kese tohumu evine götürdü. Batuhan, balkonundaki saksıya domates tohumu ekti ve her sabah onu suladı. Babası, \"Oğlum, sen artık küçük bir çiftçi oldun.\" dedi. Batuhan gururla gülümsedi."],
    sorular: [["Boş alan neye dönüştürüldü?", "Sebze bahçesine", ["Futbol sahasına", "Otoparka"]], ["Sulama nasıl düzenlendi?", "Nöbet listesiyle", ["Hiç sulanmadı", "Sadece öğretmen suladı"]], ["Fideleri ne yedi?", "Salyangozlar", ["Kediler", "Kuşlar"]], ["Batuhan ilk defa ne yedi?", "Havuç", ["Domates", "Ayçiçeği"]]] }
];
